void rds6_info_fill(struct rds_incoming *inc, struct rds_info_iterator *iter,
                    struct in6_addr *saddr, struct in6_addr *daddr, int flip)
{
    struct rds6_info_message msg;

    msg.umi = inc->i_mtu;
    msg.ulp = inc->i_ulp;
    msg.sport = inc->i_sport;
    msg.dport = inc->i_dport;
    msg.laddr = inc->i_laddr;
    msg.faddr = inc->i_faddr;

    if (flip) {
        msg.laddr = inc->i_faddr;
        msg.faddr = inc->i_laddr;
    }

    memcpy(&msg.saddr, saddr, sizeof(*saddr));
    memcpy(&msg.daddr, daddr, sizeof(*daddr));

    rds_info_copy(iter, &msg, sizeof(msg));
}

void rds6_info_fill(struct rds_incoming *inc, struct rds_info_iterator *iter,
                    struct in6_addr *saddr, struct in6_addr *daddr, int flip)
{
    struct rds6_info_message msg;

    msg.ri_family = AF_INET6;
    msg.ri_sport = inc->i_laddr;
    msg.ri_dport = inc->i_faddr;
    msg.ri_tos = 0;
    msg.ri_tclass = 0;
    msg.ri_flags = 0;

    if (flip) {
        msg.ri_laddr = *daddr;
        msg.ri_faddr = *saddr;
        __be16 port = msg.ri_sport;
        msg.ri_sport = msg.ri_dport;
        msg.ri_dport = port;
    } else {
        msg.ri_laddr = *saddr;
        msg.ri_faddr = *daddr;
    }

    rds_info_copy(iter, &msg, sizeof(msg));
}

void rds6_info_copy_message(struct rds_incoming *inc, struct rds_info_iterator *iter,
                            struct in6_addr *saddr, struct in6_addr *daddr, int flip)
{
    struct rds6_info_message msg;

    msg.udp_connected = 1;
    msg.gso_size = 0;
    msg.length = inc->i_hdr.h_len;
    msg.csum = inc->i_hdr.h_csum;
    msg.transmitted = 0;
    msg.noref = 0;
    msg.sndbuf = 0;
    msg.id = inc->i_hdr.h_laddr;
    msg.tot_len = inc->i_hdr.h_len;
    msg.urg_ptr = 0;
    msg.tcp_header_len = 0;
    msg.mss = 0;
    msg.sent_una = 0;
    msg.sent_max = 0;
    msg.rcv_nxt = 0;
    msg.tcp_ts = 0;
    msg.tcp_ts_echo = 0;
    msg.saddr = *saddr;
    msg.daddr = *daddr;

    if (flip) {
        __be16 port = msg.saddr.s6_addr16[0];
        msg.saddr = msg.daddr;
        msg.daddr.s6_addr16[0] = port;
    }

    rds_info_copy(iter, &msg, sizeof(msg));
}

void rds6_info_fill(struct rds_incoming *inc, struct rds_info_iterator *iter,
                    struct in6_addr *saddr, struct in6_addr *daddr, int flip)
{
    struct rds6_info_message msg;

    msg.iph = inc->msghdr;
    msg.iph_len = sizeof(msg.iph);
    msg.trans = inc->trans;
    msg.trans_len = inc->trans->t_len;

    if (flip) {
        msg.laddr = *daddr;
        msg.faddr = *saddr;
        msg.lport = inc->remote_port;
        msg.fport = inc->local_port;
    } else {
        msg.laddr = *saddr;
        msg.faddr = *daddr;
        msg.lport = inc->local_port;
        msg.fport = inc->remote_port;
    }

    rds_info_copy(iter, &msg, sizeof(msg));
}

void rds6_info_fill_message(struct rds_incoming *inc, struct rds_info_iterator *iter,
                            struct in6_addr *saddr, struct in6_addr *daddr, int flip)
{
    struct rds6_info_message msg;

    msg.riim_saddr = *saddr;
    msg.riim_daddr = *daddr;

    if (flip) {
        msg.riim_laddr = *daddr;
        msg.riim_faddr = *saddr;
        msg.riim_lport = inc->i_udp_port;
        msg.riim_fport = inc->i_udp_port;
    } else {
        msg.riim_laddr = *saddr;
        msg.riim_faddr = *daddr;
        msg.riim_lport = inc->i_udp_port;
        msg.riim_fport = inc->i_udp_port;
    }

    rds_info_copy(iter, &msg, sizeof(msg));
}
